import json
with open('/app/resources/treasury_bulletin_2011_03.json', 'r') as f:
    data = json.load(f)

# Search for any Canadian references
def search(obj, path=''):
    if isinstance(obj, str):
        if 'canadian' in obj.lower() or 'foreign curr' in obj.lower():
            print(f'{path}: {obj[:100]}')
    elif isinstance(obj, dict):
        for k, v in obj.items():
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, f'{path}[{i}]')

search(data)
